sys_script_include.script:
function AiToolValidateBusinessProcess(strDetails)
{
	var BusinessProcessValidate = x_snc_devtools.BusinessProcessValidate;
	var ParseJson = x_snc_devtools.ParseJson;
	var IsObject = x_snc_devtools.IsObject;

	var details = ParseJson(strDetails);
	if (IsObject(details) == false)
	{
		return { message: 'The Business Process details are not provided as a valid JSON string' };
	}
	var result = BusinessProcessValidate(details,true);
	if (result.valid == true)
	{
		result.message = 'The Business Process details are valid.';
	}
	else
	{
		result.message = 'The Business Process details are not fully valid!';
	}
	return result;
}
